"""Reproduce diagnostic summaries/CSV from frozen outcomes; no new inference."""
import csv
from collections import Counter
import numpy as np
from .common import *

def main():
    rows=[r for stage in ('development','reserved') for r in read(OUT/(stage+'.json.gz'))['records']];comparisons=read(OUT/'comparison.json');manifest=read(REVIEW/'manifest.json');refs={q['case_id']:q for q in read(ROOT/'photo2/r291/evidence/completed-review-analysis.json')['cases']};summary={}
    for stage in ('development','reserved'):
        group=[r for r in rows if r['split']==stage];before=[q for r in group for q in (comparisons[r['case_id']]['baseline_arc_measurements'] if stage=='development' else r['separator_comparison']['before']) if q['enforced']];after=[q for r in group for q in r['separator_comparison']['after'] if q['enforced']]
        summary[stage]=dict(cases=len(group),arcs=sum(len(r['separator_arcs']) for r in group),classifications=dict(Counter(a['classification'] for r in group for a in r['separator_arcs'])),direct_before=sum(q['straddled_samples'] for q in before),direct_after=sum(q['straddled_samples'] for q in after),both_banks_before=sum(q['both_banks_inside'] for q in before),both_banks_after=sum(q['both_banks_inside'] for q in after),remaining_end_around=sum(q['routed_around_samples'] for q in after),cases_with_remaining_bank_connections=sum(any(q['routed_around_samples'] for q in r['separator_comparison']['after'] if q['enforced']) for r in group),median_min_IoU=float(np.median([min(r['A']['evidence']['T8']['perturbation_IoU']) for r in group])),minimum_IoU=min(min(r['A']['evidence']['T8']['perturbation_IoU']) for r in group),alternatives=sum(bool(r['B']) for r in group))
    accepted=[q for q in manifest['cases'] if q['r291_accepted']];summary['human_references']=dict(total=len(accepted),exact=sum(comparisons[q['case_id']]['exact'] for q in accepted),immaterial=sum(not comparisons[q['case_id']]['exact'] and not comparisons[q['case_id']]['materially_changed'] for q in accepted),material=sum(comparisons[q['case_id']]['materially_changed'] for q in accepted));summary['interpretation']='Crossings are overlapping sampled constraints, not physical ownership truth or accuracy. After direct crossings are mechanically prevented where constrained; both-bank residuals reveal unresolved end-around mergers.';save(OUT/'summary.json',summary)
    with (OUT/'case-comparison.csv').open('w') as f:
        writer=csv.DictWriter(f,lineterminator='\n',fieldnames=['case_id','feature_id','x','y','split','R291_reference','human_answer','old_pixels','new_pixels','IoU_to_reference','added_pixels','removed_pixels','materially_changed','direct_before','direct_after','both_banks_after','minimum_IoU','other_features_removed','other_features_added']);writer.writeheader()
        for r in rows:
            c=comparisons.get(r['case_id'],{});writer.writerow(dict(case_id=r['case_id'],feature_id=r['feature']['id'],x=r['feature']['point'][0],y=r['feature']['point'][1],split=r['split'],R291_reference=c.get('baseline_label'),human_answer=refs.get(r['case_id'],{}).get('answer'),old_pixels=c.get('old_pixels'),new_pixels=r['A']['candidate_pixels']['pixel_count'],IoU_to_reference=c.get('iou'),added_pixels=c.get('added_pixels'),removed_pixels=c.get('removed_pixels'),materially_changed=c.get('materially_changed'),direct_before=c.get('crossings_before') if c else sum(q['straddled_samples'] for q in r['separator_comparison']['before'] if q['enforced']),direct_after=sum(q['straddled_samples'] for q in r['separator_comparison']['after'] if q['enforced']),both_banks_after=sum(q['both_banks_inside'] for q in r['separator_comparison']['after'] if q['enforced']),minimum_IoU=min(r['A']['evidence']['T8']['perturbation_IoU']),other_features_removed=';'.join(c.get('other_feature_inclusions_removed',[])),other_features_added=';'.join(c.get('other_feature_inclusions_added',[]))))
    print('Summary/CSV regenerated:',len(rows),'cases;',summary['human_references'])
if __name__=='__main__':main()
